WITH parsed AS (SELECT id, service, host, level, context, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, context['region'] AS region, context['trace'] AS trace FROM app_logs) SELECT tier, SIZE(COLLECT_SET(tier)) AS num_tiers, SIZE(COLLECT_SET(level)) AS num_levels, COUNT(DISTINCT level) AS distinct_levels, COUNT(DISTINCT user_tier) AS distinct_user_tiers, SORT_ARRAY(COLLECT_SET(service)) AS service_list FROM parsed GROUP BY tier ORDER BY distinct_user_tiers NULLS FIRST;
